// magpie-mlx-serve — magpie plugin that turns mlx-serve's video models
// (MiniMax-H3, LTX-Video) into generate_video videomakers.
//
// magpie's gateway speaks the OpenAI videos API (POST /videos,
// GET /videos/{id}, GET /videos/{id}/content) to any provider whose model
// declares output video; for a plugin provider those requests go through
// the plugin's own fetch (internal/gateway/video.go, customVideomakers).
// This plugin answers them by translating to mlx-serve's
// POST /v1/video/generations (SSE), then muxing the returned rgb8 frames
// and pcm_s16le audio into an mp4 with ffmpeg.

import { videoFacade, mlxBase } from "./server.mjs"

// Distinct from magpie's built-in mlx-serve preset id on purpose: a plugin
// provider whose id is taken gets "-plugin" appended (docs, Provider ids),
// and the builtin preset covers chat only. Video rides its own provider.
const PROVIDER = "mlx-serve-video"

export const MlxServePlugin = async (_input, options) => {
  const base = mlxBase(options)

  return {
    config: async (cfg) => {
      cfg.provider ??= {}
      cfg.provider[PROVIDER] ??= {
        name: "MLX-Serve Video",
        npm: "@ai-sdk/openai-compatible",
        api: `${base}/v1`,
        // filled per account by the provider hook below; kept empty here so
        // nothing pretends to chat before the server has been asked
        models: {},
      }
    },

    auth: {
      provider: PROVIDER,
      // mlx-serve on localhost needs no key. magpie accounts are built
      // around a sign-in, so: one method, the value is never read.
      methods: [{ type: "api", label: "Local mlx-serve — no key needed, enter anything" }],
      async loader() {
        return {
          baseURL: `${base}/v1`,
          fetch: (input, init) => videoFacade(input, init, base),
        }
      },
    },

    provider: {
      id: PROVIDER,
      async models() {
        try {
          const r = await fetch(`${base}/v1/models`)
          if (!r.ok) return {}
          const list = await r.json()
          const rows = list.data ?? list.models ?? []
          const out = {}
          for (const m of rows) {
            const caps = m.capabilities ?? []
            if (!caps.includes("video")) continue
            out[m.id] = {
              id: m.id,
              name: m.name ?? m.id,
              attachment: true,
              // output video is what makes magpie's gateway a videomaker
              // of the model (capabilities.output.video); input text and
              // image cover t2v and first-frame conditioning
              capabilities: {
                temperature: false,
                reasoning: false,
                attachment: true,
                toolcall: false,
                input: { text: true, image: true, audio: false, video: false, pdf: false },
                output: { text: false, image: false, audio: false, video: true, pdf: false },
                interleaved: false,
              },
            }
          }
          return out
        } catch {
          return {}
        }
      },
    },
  }
}

// The OpenAI-videos facade over mlx-serve's /v1/video/generations.
//
// magpie sends, through this fetch (it is the plugin loader's fetch):
//   POST {base}/v1/videos            {"model","prompt","seconds"?,"size"?,
//                                     "input_reference"? (data URL, first
//                                     frame),"last_frame"?,"reference_images"?}
//   GET  {base}/v1/videos/{id}       -> OpenAI video object
//   GET  {base}/v1/videos/{id}/content -> the mp4 bytes
//
// mlx-serve answers generation with rgb8 frames (base64 in "data") and
// pcm_s16le audio (base64 in "audio_data"), 24 fps; SSE with stream:true
// gives progress events ending in a complete one. ffmpeg muxes them.

import { spawn } from "node:child_process"
import { mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises"
import { tmpdir } from "node:os"
import { join } from "node:path"

const DEFAULT_BASE = "http://127.0.0.1:11234"

// magpie starts plugin hosts on demand and recycles them, so module memory
// does not outlive a call: every job is a JSON record beside its mp4, under
// this dir, and a fresh host reads them back. Finished videos stay
// downloadable across host restarts; an in-flight one is honestly "failed"
// (mlx-serve aborts generation when the SSE reader goes).
const JOBS_DIR = join(tmpdir(), "magpie-mlx-serve-jobs")

// jobs live in the plugin host process; ids are random, so a host restart
// only loses videos still in flight (magpie says "no provider ... makes
// videos" shaped errors from the 404 below)
const jobs = new Map()
// from the job's last activity (a progress event, a poll), not its start:
// an hour-long generation must not be swept out from under a poller
const JOB_TTL_MS = 2 * 60 * 60 * 1000
const JOBS_KEPT = 24

const jobFile = (id) => join(JOBS_DIR, `${id}.json`)
const mp4File = (id) => join(JOBS_DIR, `${id}.mp4`)

async function saveJob(job) {
  try {
    await mkdir(JOBS_DIR, { recursive: true })
    const { base, mp4, ...record } = job
    await writeFile(jobFile(job.id), JSON.stringify({ ...record, file: job.file ?? null }))
  } catch {}
}

// a host that restarted reads the record back
async function loadJob(id) {
  if (jobs.has(id)) return jobs.get(id)
  try {
    const job = JSON.parse(await readFile(jobFile(id), "utf8"))
    jobs.set(id, job)
    return job
  } catch {
    return null
  }
}

// mlxBase is where mlx-serve is: the plugin's options (magpie plugin
// options mlx-serve-video '{"url": "..."}'), an env var, or the default.
export function mlxBase(options) {
  const u = options?.url || options?.mlxServeUrl || process.env?.MLX_SERVE_URL || DEFAULT_BASE
  return String(u).replace(/\/+$/, "")
}

export function videoFacade(input, init, base) {
  sweep()
  const method = (init?.method ?? (typeof input === "object" && input?.method) ?? "GET").toUpperCase()
  let url
  try {
    url = new URL(typeof input === "string" || input instanceof URL ? input : input.url)
  } catch {
    return json({ error: { message: `mlx-serve plugin: unparseable request URL ${String(input)}` } }, 400)
  }
  let m
  if (url.pathname === "/v1/videos" && method === "POST") return postVideos(input, init, base)
  if ((m = url.pathname.match(/^\/v1\/videos\/([A-Za-z0-9_-]+)$/)) && method === "GET") {
    return videoStatus(m[1])
  }
  if ((m = url.pathname.match(/^\/v1\/videos\/([A-Za-z0-9_-]+)\/content$/)) && method === "GET") {
    return videoContent(m[1])
  }
  // everything else (chat, model lists, …) goes to mlx-serve untouched
  return fetch(input, init ?? {})
}

async function postVideos(input, init, base) {
  const body = await readJson(input, init)
  if (!body || typeof body.prompt !== "string" || !body.prompt) {
    return json({ error: { message: "mlx-serve plugin: the request needs a prompt" } }, 400)
  }
  const id = "mlxb" + Date.now().toString(36) + Math.random().toString(36).slice(2, 8)
  const job = {
    id, created: Date.now(), model: body.model ?? "", status: "queued", progress: 0,
    seconds: body.seconds ?? "", mp4: null, error: null, base,
  }
  jobs.set(id, job)
  saveJob(job)
  run(job, toMlx(body), base).catch((err) => fail(job, err))
  const out = { id, object: "video", created_at: Math.floor(job.created / 1000), status: "queued", model: job.model }
  if (body.seconds) out.seconds = String(body.seconds)
  return json(out)
}

// OpenAI's video body -> mlx-serve's /v1/video/generations body
function toMlx(body) {
  const out = { model: body.model, prompt: body.prompt }
  if (body.seconds !== undefined && body.seconds !== "") {
    const n = Math.round(parseFloat(body.seconds) * 24)
    if (n > 0) out.num_frames = n
  }
  const size = parseSize(body.size)
  if (size) {
    out.width = size.width
    out.height = size.height
  }
  if (body.input_reference) out.first_frame_image = stripDataUrl(body.input_reference)
  if (body.last_frame) out.last_frame_image = stripDataUrl(body.last_frame)
  if (Array.isArray(body.reference_images) && body.reference_images.length > 0) {
    out.ref_images = body.reference_images.map(stripDataUrl)
  }
  // pass mlx-serve's own knobs through when the caller names them
  for (const k of ["steps", "seed", "fast", "turbo", "chain_windows", "negative_prompt", "guidance_scale"]) {
    if (body[k] !== undefined) out[k] = body[k]
  }
  return out
}

// "1024x1024" -> multiples of 32 (mlx-serve requires it); "16:9" -> a
// 768p-class canvas of that ratio; anything odd is left to the server
function parseSize(size) {
  if (!size || typeof size !== "string") return null
  let m = size.match(/^(\d+)\s*x\s*(\d+)$/i)
  if (m) return { width: snap32(+m[1]), height: snap32(+m[2]) }
  m = size.match(/^(\d+)\s*:\s*(\d+)$/)
  if (m) {
    const area = 1024 * 576
    const r = +m[1] / +m[2]
    const h = Math.sqrt(area / r)
    return { width: snap32(h * r), height: snap32(h) }
  }
  return null
}

const snap32 = (n) => Math.max(64, Math.round(n / 32) * 32)

const stripDataUrl = (s) => String(s).replace(/^data:[^,]*,/, "")

async function run(job, mlx, base) {
  job.status = "in_progress"
  const res = await fetch(`${base}/v1/video/generations`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ ...mlx, stream: true }),
  })
  if (!res.ok) {
    const t = await res.text().catch(() => "")
    throw new Error(`mlx-serve answered ${res.status}: ${t.slice(0, 400)}`)
  }
  const done = await consume(res, (ev) => {
    if (ev?.type === "progress") {
      job.touched = Date.now()
      let p = Number(ev.progress ?? 0)
      if (p <= 1) p *= 100
      p = Math.max(job.progress, Math.min(99, Math.round(p)))
      if (p !== job.progress) {
        job.progress = p
        saveJob(job)
      }
    }
  })
  if (!done || !done.data) throw new Error("mlx-serve finished without a complete payload")
  const frames = done.frames, width = done.width, height = done.height
  const rgb = Buffer.from(done.data, "base64")
  if (frames * height * width * 3 !== rgb.length) {
    throw new Error(`mlx-serve's frames don't add up: ${rgb.length} bytes for ${frames}x${height}x${width}x3`)
  }
  const fps = done.fps ?? 24
  let pcm = null, rate = done.audio_sample_rate ?? 32000, channels = done.audio_channels ?? 2
  if (done.audio_data) pcm = Buffer.from(done.audio_data, "base64")
  const mp4 = await mux(rgb, pcm, width, height, fps, rate, channels)
  await mkdir(JOBS_DIR, { recursive: true })
  await writeFile(mp4File(job.id), mp4)
  job.file = mp4File(job.id)
  job.seconds = (frames / fps).toFixed(2)
  job.status = "completed"
  job.progress = 100
  await saveJob(job)
}

// SSE progress -> complete; a server that answers plain JSON works too
async function consume(res, onEvent) {
  const type = res.headers.get("content-type") ?? ""
  if (!/event-stream/i.test(type)) {
    const ev = await res.json().catch(() => null)
    return ev?.type === "complete" || ev?.data ? ev : null
  }
  const reader = res.body.getReader()
  const decoder = new TextDecoder()
  let buf = "", complete = null
  for (;;) {
    const { done, value } = await reader.read()
    if (done) break
    buf += decoder.decode(value, { stream: true })
    let nl
    while ((nl = buf.indexOf("\n")) >= 0) {
      const line = buf.slice(0, nl).replace(/\r$/, "")
      buf = buf.slice(nl + 1)
      const ev = parseEvent(line)
      if (!ev) continue
      if (ev.type === "complete") complete = ev
      else onEvent(ev)
    }
  }
  const last = parseEvent(buf)
  if (last?.type === "complete") complete = last
  else if (last) onEvent(last)
  return complete
}

function parseEvent(line) {
  const s = line.trim()
  if (!s || s.startsWith(":")) return null
  const payload = s.startsWith("data:") ? s.slice(5).trim() : s
  if (!payload.startsWith("{")) return null
  try {
    return JSON.parse(payload)
  } catch {
    return null
  }
}

async function mux(rgb, pcm, width, height, fps, rate, channels) {
  const dir = await mkdtemp(join(tmpdir(), "mlx-video-"))
  try {
    const rgbPath = join(dir, "in.rgb")
    await writeFile(rgbPath, rgb)
    const args = [
      "-y", "-loglevel", "error",
      "-f", "rawvideo", "-pix_fmt", "rgb24", "-s", `${width}x${height}`, "-r", String(fps), "-i", rgbPath,
    ]
    let pcmPath = null
    if (pcm && pcm.length > 0) {
      pcmPath = join(dir, "in.pcm")
      await writeFile(pcmPath, pcm)
      args.push("-f", "s16le", "-ar", String(rate), "-ac", String(channels), "-i", pcmPath)
    }
    const outPath = join(dir, "out.mp4")
    args.push(
      "-c:v", "libx264", "-preset", "veryfast", "-crf", "20", "-pix_fmt", "yuv420p",
      ...(pcmPath ? ["-c:a", "aac", "-b:a", "128k", "-shortest"] : []),
      "-movflags", "+faststart", outPath,
    )
    await ffmpeg(args)
    return await readFile(outPath)
  } finally {
    rm(dir, { recursive: true, force: true }).catch(() => {})
  }
}

function ffmpeg(args) {
  return new Promise((resolve, reject) => {
    let p
    try {
      p = spawn("ffmpeg", args, { stdio: ["ignore", "ignore", "pipe"] })
    } catch (err) {
      reject(new Error(`ffmpeg could not be started (brew install ffmpeg): ${err}`))
      return
    }
    let stderr = ""
    p.stderr.on("data", (d) => { stderr += d; if (stderr.length > 8000) stderr = stderr.slice(-4000) })
    p.on("error", (err) => {
      if (err.code === "ENOENT") reject(new Error("ffmpeg not found — install it (macOS: brew install ffmpeg)"))
      else reject(err)
    })
    p.on("close", (code) => {
      if (code === 0) resolve()
      else reject(new Error(`ffmpeg exited ${code}: ${stderr.trim().slice(-500)}`))
    })
  })
}

function fail(job, err) {
  job.status = "failed"
  job.error = err?.message ?? String(err)
  saveJob(job)
}

async function videoStatus(id) {
  const job = await loadJob(id)
  if (!job) return json({ error: { message: `mlx-serve plugin: no video ${id} here (it is older than the job store, or the store was wiped)` } }, 404)
  job.touched = Date.now()
  const out = {
    id,
    object: "video",
    created_at: Math.floor(job.created / 1000),
    status: job.status,
    progress: job.progress,
    model: job.model,
  }
  if (job.seconds) out.seconds = String(job.seconds)
  if (job.status === "completed") out.video = { url: `${job.base}/v1/videos/${id}/content` }
  if (job.status === "failed") out.error = { code: "failed", message: job.error }
  return json(out)
}

async function videoContent(id) {
  const job = await loadJob(id)
  if (!job) return json({ error: { message: `mlx-serve plugin: no video ${id} here` } }, 404)
  if (job.status !== "completed") {
    return json({ error: { message: `the video is still ${job.status}` } }, 409)
  }
  try {
    const bytes = await readFile(job.file ?? mp4File(id))
    return new Response(bytes, {
      status: 200,
      headers: { "content-type": "video/mp4", "content-length": String(bytes.length) },
    })
  } catch {
    return json({ error: { message: `the video's file is gone (${job.file ?? mp4File(id)}); the job store was cleaned` } }, 404)
  }
}

async function readJson(input, init) {
  let body = init?.body
  if (body === undefined && typeof input === "object" && typeof input.text === "function") {
    body = await input.clone().text()
  }
  if (body === undefined || body === null) return null
  try {
    return JSON.parse(typeof body === "string" ? body : Buffer.from(body).toString("utf8"))
  } catch {
    return null
  }
}

function sweep() {
  const now = Date.now()
  for (const [id, job] of jobs) {
    if (now - (job.touched ?? job.created) > JOB_TTL_MS) {
      jobs.delete(id)
      rm(jobFile(id), { force: true }).catch(() => {})
      rm(mp4File(id), { force: true }).catch(() => {})
    }
  }
  if (jobs.size <= JOBS_KEPT) return
  const oldest = [...jobs.values()].sort((a, b) => (a.touched ?? a.created) - (b.touched ?? b.created))
  for (const job of oldest.slice(0, jobs.size - JOBS_KEPT)) {
    jobs.delete(job.id)
    rm(jobFile(job.id), { force: true }).catch(() => {})
    rm(mp4File(job.id), { force: true }).catch(() => {})
  }
}

function json(obj, status = 200) {
  return new Response(JSON.stringify(obj), { status, headers: { "content-type": "application/json" } })
}
